"""Figure for the look-back study -> reports/figures/bl_lb_logic.png"""
import sys, os, warnings; sys.path.insert(0, '.'); warnings.filterwarnings('ignore')
import numpy as np, pandas as pd, matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
from bl_common import OUT
FIG = os.path.join(os.path.dirname(OUT), 'reports', 'figures'); os.makedirs(FIG, exist_ok=True)
SC = pd.read_csv(f'{OUT}/bl_lb_scan.csv'); LS = pd.read_csv(f'{OUT}/bl_lb_live_scan.csv'); DF = pd.read_csv(f'{OUT}/bl_lb_defs.csv'); SE = pd.read_csv(f'{OUT}/bl_lb_live.csv'); HZ = pd.read_csv(f'{OUT}/bl_lb_hazard.csv')
fig, ax = plt.subplots(2, 2, figsize=(13.5, 9.5))
a = ax[0, 0]; a.plot(SC.L_min, SC.hit_rate * 100, '-', color='#7f7f7f', label='last completed minute close'); a.plot(LS.L_min, LS.hit_rate_live_proxy * 100, 'o-', color='#d62728', label='live-spot proxy (order second)'); a.axvline(15, color='k', ls=':', lw=1); a.set_xlabel('look-back length L (minutes)'); a.set_ylabel('% of reactive pairs whose strike = ATM + 1 step toward the L-minute move'); a.set_ylim(55, 95); a.set_title('A. 15 minutes is not special: any 10–60 min look-back fits'); a.legend(fontsize=8)
a = ax[0, 1]; D = DF.sort_values('hit_rate'); a.barh(range(len(D)), D.hit_rate * 100, color=['#d62728' if d.startswith('rolling') else '#1f77b4' for d in D['direction definition']]); a.set_yticks(range(len(D))); a.set_yticklabels(D['direction definition'], fontsize=7); a.set_xlabel('hit rate (%)'); a.set_title('B. Rolling windows (red) beat anchored definitions (blue)')
a = ax[1, 0]; x = np.arange(len(SE)); a.bar(x - .2, SE.hit_bar * 100, .4, color='#7f7f7f', label='last completed minute close'); a.bar(x + .2, SE.hit_live_proxy * 100, .4, color='#d62728', label='live-spot proxy'); a.set_xticks(x); a.set_xticklabels(['0-9', '10-19', '20-29', '30-39', '40-49', '50-59']); a.set_xlabel('second of the minute of the order'); a.set_ylabel('hit rate (%)'); a.set_ylim(50, 100); a.set_title('C. The strike fits the live spot at the order second'); a.legend(fontsize=8, loc='lower left')
a = ax[1, 1]; h = HZ[HZ.kind == 'signed 15-min move']; a.bar(range(len(h)), h.per1000, color=['#d62728', '#d62728', '#7f7f7f', '#2ca02c', '#2ca02c']); a.set_xticks(range(len(h))); a.set_xticklabels([g.replace(' ', '\n', 1) for g in h.group], fontsize=7); a.set_ylabel('reactive pairs per 1000 cycle-minutes (10:30–15:15)'); a.set_title('D. Move size/direction hardly change WHEN; flat markets are lower')
fig.suptitle('Algo 8 reactive pairs: how the look-back works — in-sample, D-1, 363 pairs', fontsize=11); fig.tight_layout(); fig.savefig(f'{FIG}/bl_lb_logic.png', dpi=140); print('saved')
